<script setup lang="ts">
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {useApp} from '../stores/app'
import {useAdminProfile} from '../stores/adminProfile'
import history from '../data/pm-history.json'
import '../styles/admin-app-14.css'
function printDocument(){window.print()}
const route=useRoute(),app=useApp(),admin=useAdminProfile(),query=ref('')
const section=computed(()=>route.path.split('/').at(-1)),title=computed(()=>section.value==='history'?'점검 이력':section.value==='contacts'?'관할 담당자 연락처':'통제 전달 문서')
const rows=computed(()=>history.H.filter(row=>row.join(' ').includes(query.value)))
const contacts=computed(()=>{try{return JSON.parse(localStorage.getItem('routel-jurisdiction-contacts:'+(app.account?.regions?.map(r=>r.name).join(' · ')||admin.region))||'[]')}catch{return []}})
</script>
<template><div class="wire-page mobile-page page-admin-app-14"><div class="ph adm"><header class="ah"><RouterLink to="/admin-app/screen-14">‹</RouterLink><span>{{title}}</span><button type="button" class="theme-toggle" aria-label="라이트·다크 전환" @click="app.themeToggle()">◐</button></header><main class="bd app-extra-body"><template v-if="section==='history'"><p class="sub">구성 예시 · 실제 점검 기록 연동 전입니다.</p><input v-model="query" type="search" placeholder="설비·시설·조치 내용 검색" aria-label="점검 이력 검색"><article v-for="row in rows" :key="String(row[0])+row[1]" class="card"><small>{{row[0]}}</small><h2>{{row[1]}} · {{row[2]}}</h2><p>{{row[3]}}</p><p>{{row[4]}} · {{row[5]}}</p><p>{{row[7]}} · {{row[8]}} → {{row[9]}}점</p></article><p v-if="!rows.length">검색 결과가 없습니다.</p></template><template v-else-if="section==='contacts'"><p>{{admin.region}}</p><article v-for="[id,label] in [['community','관할 주민센터'],['police','지역 경찰관'],['civilian','민간 조력자']]" :key="id" class="card"><h2>{{label}}</h2><template v-for="contact in contacts.filter((c:any)=>c.id===id)" :key="contact.id"><p>{{contact.organization||'소속 미등록'}} · {{contact.nameOfPerson||'담당자 미등록'}}</p><a v-if="contact.phone" :href="'tel:'+contact.phone.replace(/[^\d+]/g,'')">{{contact.phone}}</a></template><p v-if="!contacts.some((c:any)=>c.id===id&&c.phone)">연락처 미등록</p></article></template><template v-else><p class="sub">구성 예시 · 실제 통제 문서가 아닙니다.</p><article class="card"><h2>도로 통제 정보 전달서</h2><dl><dt>시설</dt><dd>초량1지하차도</dd><dt>구분</dt><dd>통제 시작</dd><dt>사유</dt><dd>침수 위험</dd><dt>통제 방식</dt><dd>입구 차단 · 전광판 우회 안내</dd><dt>담당 지역</dt><dd>{{admin.region}}</dd></dl></article><button type="button" class="btn" @click="printDocument">문서 인쇄 · PDF 저장</button></template></main><nav class="tb"><RouterLink to="/admin-app/screen-3">현황</RouterLink><RouterLink to="/admin-app/screen-4">통제</RouterLink><RouterLink to="/admin-app/screen-9">예지보전</RouterLink><RouterLink to="/admin-app/screen-13">알림</RouterLink><RouterLink to="/admin-app/screen-14">더보기</RouterLink></nav></div></div></template>
<style scoped>.app-extra-body{display:flex;flex-direction:column;gap:14px}.app-extra-body h2{font-size:16px;margin:8px 0}.app-extra-body p{font-size:14px;line-height:1.6}.app-extra-body input{padding:12px;background:var(--surface);color:inherit;border:1px solid var(--line)}dl{display:grid;grid-template-columns:90px 1fr;gap:16px;font-size:14px}dd{margin:0}.ah>a{color:inherit;text-decoration:none;font-size:24px}.ah>button{margin-left:auto}</style>
